#!/usr/bin/env python3
"""Adopt a verified preflight WAV with its actual fixed model/seed/batch recipe.

Run only after the main batch. Does not synthesize, alter wording, or change
other line fingerprints. Refresh manifests with render-voices-qwen.py --ids.
"""
from pathlib import Path
import argparse,importlib.util,json,shutil,time,subprocess,wave,fcntl
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--work-dir',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--control',type=Path,required=True);p.add_argument('--source-script',type=Path,required=True);p.add_argument('--model',type=Path,help='Pinned Base model directory (default: work-dir/models/1.7B)');args=p.parse_args()
r=args.work_dir
run_lock=(r/'render.lock').open('a+')
try:fcntl.flock(run_lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
except BlockingIOError:raise SystemExit('Renderer is still running; adopt only after completion.')
spec=importlib.util.spec_from_file_location('qwen_renderer',r/'render-voices-qwen.py');renderer=importlib.util.module_from_spec(spec);spec.loader.exec_module(renderer)
control=json.loads(args.control.read_text());id=control['id'];source_wav=args.control.with_suffix('.wav');assert renderer.digest(source_wav)==control['sha256']
manifest=json.loads((args.output/'manifest.json').read_text());base=manifest['models']['base'];assert control['model']==base['id']
model_dir=args.model or r/'models'/'1.7B';provenance=json.loads((model_dir/'provenance.json').read_text())
assert provenance['id']==base['id'] and provenance['revision']==base['revision']
weight_entry=next(x for x in provenance['files'] if x['path']=='model.safetensors')
assert renderer.digest(model_dir/'model.safetensors')==weight_entry['lfs']['oid']==base['sha256']
for field,value in [('modelRevision',base['revision']),('modelSha256',base['sha256'])]:
 if field in control:assert control[field]==value
inputs_path=r/'voice-qwen.json';inputs=json.loads(inputs_path.read_text());item=inputs['lines'][id];cast=json.loads((r/'voice-cast.json').read_text());profile=cast[item['speakerId']]
assert control['text']==item['sourceText'] and control['synthesisText']==item['synthesisText']
assert control['referenceSha256']==profile['referenceSha256'] and control['referenceId']==profile['referenceId']
assert item['speakerId']==control['speakerId']
batch_ids=control.get('batchIds',[id]);seed=control['seed'];texts=[]
for member in batch_ids:
 evidence=json.loads((args.control.parent/(member+'.json')).read_text());assert evidence['seed']==seed and evidence['model']==base['id'] and evidence['referenceSha256']==profile['referenceSha256'];texts.append(evidence['synthesisText'])
assert texts[batch_ids.index(id)]==item['synthesisText']
for member in batch_ids:
 evidence_path=args.control.parent/(member+'.json');evidence=json.loads(evidence_path.read_text())
 assert renderer.digest(evidence_path.with_suffix('.wav'))==evidence['sha256']
# The only accepted controls were generated by our fixed preflight scripts.
source_code=args.source_script.read_text()
for required in ['non_streaming_mode=True','max_new_tokens=400','do_sample=True','top_p=.9','temperature=.8']:
 assert required in source_code, 'Unsupported preflight configuration: '+required
archive=r/'retakes'/id/'before-control-adoption';archive.mkdir(parents=True,exist_ok=True)
raw=r/'raw'/(id+'.wav');mp3=args.output/(id+'.mp3');record_path=r/'records'/(id+'.json')
for path in [raw,mp3,record_path]:
 if path.exists():shutil.copyfile(path,archive/path.name)
evidence_dir=r/'adopted-controls'/id;evidence_dir.mkdir(parents=True,exist_ok=True)
for member in batch_ids:
 for suffix in ['.json','.wav']:
  path=args.control.parent/(member+suffix);shutil.copyfile(path,evidence_dir/path.name)
shutil.copyfile(args.source_script,evidence_dir/args.source_script.name)
validation={'controlMetadataSha256':renderer.digest(args.control),'sourceScriptSha256':renderer.digest(args.source_script),'pinnedModel':base,'pinnedProvenanceSha256':renderer.digest(model_dir/'provenance.json'),'validatedAtUnix':time.time(),'historicalMetadataMissing':[key for key in ['modelRevision','modelSha256','generation'] if key not in control],'provenanceNote':'The original preflight sidecar is preserved unchanged. Its model ID, seed, batch, text and reference SHA are original recorded evidence. Revision/weight SHA are validated against the same pinned local model used throughout this run, rather than retroactively inserted into the original sidecar.'}
renderer.write_json(evidence_dir/'adoption-validation.json',validation)
shutil.copyfile(model_dir/'provenance.json',evidence_dir/'model-provenance.json')
previous={'batchId':item.get('batchId'),'seed':item['seed'],'attempt':item.get('attempt',0)};item.setdefault('previousAttempts',[]).append(previous);item['attempt']=int(item.get('attempt',0))+1
batch_id='verified-control-'+id;item['batchId']=batch_id;item['seed']=seed;inputs['batches'][batch_id]={'ids':batch_ids,'seed':seed,'texts':texts};renderer.write_json(inputs_path,inputs)
shutil.copyfile(source_wav,raw)
line_encoding=renderer.encoding_for(item);filters=renderer.audio_filters(line_encoding)
temp_mp3=mp3.with_name(mp3.name+'.tmp');started=time.monotonic();subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-i',str(raw),'-af',filters,'-ac','1','-ar','24000','-codec:a','libmp3lame','-b:a','128k','-map_metadata','-1','-f','mp3',str(temp_mp3)],check=True);temp_mp3.replace(mp3)
probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','json',str(mp3)],text=True));duration=round(float(probe['format']['duration']),3)
with wave.open(str(raw),'rb') as f:sr=f.getframerate();raw_duration=f.getnframes()/sr
line_generation={**renderer.GENERATION,'batchIds':batch_ids,'batchSeed':seed,'batchTextsSha256':renderer.canonical_hash(texts)}
recipe={'attempt':item['attempt'],'model':base,'synthesisText':item['synthesisText'],'sourceText':item['sourceText'],'referenceSha256':profile['referenceSha256'],'seed':seed,'generation':line_generation,'encoding':line_encoding,'method':'synthetic-reference-conditioned'}
entry={'url':f'assets/audio/voices/{id}.mp3','speakerId':item['speakerId'],'voice':profile['voice'],'duration':duration,'provider':renderer.PROVIDER,'license':'Apache-2.0','sha256':renderer.digest(mp3),'bytes':mp3.stat().st_size,'model':base['id'],'modelRevision':base['revision'],'referenceId':profile['referenceId'],'referenceSha256':profile['referenceSha256'],'textSha256':renderer.text_hash(item['sourceText']),'renderInputSha256':renderer.text_hash(item['synthesisText'])}
if item.get('encodingOverrides'):entry['encodingOverrides']=item['encodingOverrides']
record={'status':'complete','id':id,'speakerId':item['speakerId'],'text':item['sourceText'],'synthesisText':item['synthesisText'],'duration':duration,'rawDuration':raw_duration,'sampleRate':sr,'sha256':entry['sha256'],'rawSha256':renderer.digest(raw),'fingerprint':renderer.canonical_hash(recipe),'runtimeEntry':entry,'generation':recipe,'renderSeconds':round(time.monotonic()-started,3),'batchRenderSeconds':control.get('batchRenderSeconds',control.get('render_seconds')),'adoptedFrom':{'controlRawSha256':control['sha256'],'controlMetadataSha256':renderer.digest(args.control),'sourceScriptSha256':renderer.digest(args.source_script),'controlFolder':str(args.control.parent),'validationSha256':renderer.digest(evidence_dir/'adoption-validation.json'),'historicalMetadataMissing':validation['historicalMetadataMissing'],'reason':'Verified correct preflight take of the same line and original synthetic voice; actual seed and batch are retained'}}
renderer.write_json(record_path,record);(r/'ready.marker.json').unlink(missing_ok=True)
print(json.dumps({'adopted':id,'duration':duration,'sha256':entry['sha256'],'actualSeed':seed,'actualBatch':batch_ids},ensure_ascii=False))
